"""Generate matching, readable public HTML and offline Flutter legal content.

This generator does not certify compliance or turn planned safeguards into facts.
Publication remains a draft while the operator's review fields are incomplete.
"""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'game/platform'

def build():
 c=json.loads((ROOT/'legal/operator.json').read_text(encoding='utf-8'));email=c['supportEmail']
 missing=[]
 if not c.get('operatorLegalName'):missing.append('الاسم القانوني للمالك أو الجهة المشغلة لم يُستكمل؛ Plazr اسم المشروع المعلن.')
 if not c.get('operatingCountry'):missing.append('دولة التشغيل والقانون المنطبق لم يُحددا.')
 if not c.get('supportMailboxVerified'):missing.append('عنوان الدعم المحدد يحتاج تأكيد تفعيله واستقبال الرسائل.')
 if not c.get('infrastructureRetentionReviewed'):missing.append('مدد الاحتفاظ بسجلات الاستضافة والنسخ الاحتياطية ومواقع الاستضافة تحتاج توثيقًا فعليًا.')
 if c.get('audienceIncludesUnder13') and not c.get('childrenSafeguardsReviewed'):missing.append('الجمهور يشمل دون 13 سنة، لكن موافقة ولي الأمر وحماية تجربة الأطفال غير مطبقتين في النسخة المراجعة.')
 draft=c.get('publicationStatus')!='published' or bool(missing)
 pages=[]
 def page(key,title,summary,sections):pages.append({'id':key,'title':title,'summary':summary,'sections':[{'title':t,'paragraphs':p} for t,p in sections]})
 page('privacy','سياسة الخصوصية','كيف تتعامل Plazr مع بيانات الحساب واللعب والمحادثات والأجهزة.',[
 ('1. نطاق الوثيقة والجهة المشغلة',[
 'تصف هذه الوثيقة موقع Plazr وتطبيقه وخدمات الحساب والمساحات والمباريات المرتبطة به. اسم المشروع المعلن هو Plazr. '+('الجهة المشغلة: '+c['operatorLegalName']+'.' if c.get('operatorLegalName') else 'لم يُستكمل الاسم القانوني للمالك أو الجهة المشغلة، ولا ندعي أن الاسم التجاري جهة مسجلة.'),
 ('دولة التشغيل: '+c['operatingCountry']+'.' if c.get('operatingCountry') else 'لم تُحدد دولة التشغيل أو القانون المنطبق بعد. لا تُنسب الخدمة في هذه المسودة إلى دولة لم يؤكدها المشغّل.')+' للتواصل بخصوص البيانات: '+email+'.']),
 ('2. البيانات التي نعالجها',[
 'الحساب: معرّف الحساب واسم المستخدم، والبريد وحالة التحقق ومعرّف مزود المصادقة عند ربط حساب. يمكن بدء الاستخدام بحساب ضيف ذي معرّف واسم مولّدين؛ الضيف ليس جلسة خالية من جمع البيانات. بيانات الدخول ضرورية للتحقق واستعادة الوصول وإدارة الجلسات.',
 'الملف والمحتوى: الصورة التي تختارها، والنبذة الاختيارية، والملصقات والأغطية المجهزة، ورسائل المساحات والمباريات، والملصقات المرسلة، وعلاقات الصداقة وطلباتها، والبلاغات وإجراءات الإشراف.',
 'اللعب والمتجر: العضوية في الطاولات وأوامر اللعب وحالة المباراة والنتائج والتقدم والسمعة والرصيد الافتراضي والمقتنيات وسجل عملياتها. النسخة الحالية تستخدم عملات افتراضية ولا تتضمن مسار دفع نقدي مدمجًا أو جمع بيانات بطاقات دفع.',
 'الاتصال والأجهزة: رموز جلسات خاصة، نوع الجهاز والمتصفح، إنشاء الجلسة وآخر نشاط وانتهاؤها، ودولة تقريبية إن وفرتها بوابة موثوقة مفعلة. يتلقى الخادم ومزود الشبكة عنوان IP عند الاتصال؛ قد يظهر في سجلات البوابة طبقًا لإعدادات النشر. لا يحتوي سجل الأجهزة المعروض على موقع GPS دقيق.']),
 ('3. لماذا نستخدم هذه البيانات؟',[
 'لإنشاء الحساب وربطه واستعادة دخوله، وإظهار الملف والمقتنيات، وتوصيل الرسائل والأدوار وحالة المباريات، وحفظ التقدم، وإدارة الأجهزة وإنهاء جلساتها، ومنع إساءة الاستخدام والتحقيق في البلاغات والأعطال وتنفيذ حذف الحساب.',
 'لا تتضمن النسخة المراجعة أدوات إعلانات سلوكية أو SDK لتحليلات تسويقية. هذا وصف للوظائف الحالية، وليس موافقة مسبقة على إضافة تتبع جديد. يلزم إعلان أي تغيير وتحديث الوثائق والاختيارات ذات الصلة قبل تفعيله.']),
 ('4. ما الذي يراه الآخرون؟',[
 'قد يرى اللاعبون اسم المستخدم والصورة والنبذة والمقتنيات المعروضة والسمعة وإحصاءات اللعب والحضور المرتبط بالمساحة أو المباراة. البريد ورموز الجلسات لا يظهران في الملف العام.',
 'رسائل المساحة يراها المشاركون فيها، ورسائل المباراة يراها من يملك حق الوصول لمحادثتها، بما في ذلك المشاهدون بحسب قواعد المباراة. تعالج الخوادم هذه الرسائل؛ لا نقدم وعدًا بأنها مشفرة من طرف إلى طرف. قد يراجع المشرفون المحتوى والبلاغات ضمن صلاحياتهم. لا تنشر معلومات حساسة أو بيانات شخصية عن غيرك؛ لا نتحكم في لقطات الشاشة التي يحتفظ بها الآخرون.']),
 ('5. التخزين على جهازك والصلاحيات',[
 'نستخدم كوكي جلسة لازمة للدخول على الويب، وتخزينًا محليًا لتفضيلات الواجهة، وتخزين ملفات الألعاب لإعادة استخدامها بدل تنزيلها كل مرة. التطبيق يحتفظ ببيانات جلسة في التخزين الآمن للنظام. لا تُخزن طلبات الحساب أو المحادثات ضمن ذاكرة التخزين المسبق العامة لملفات الألعاب.',
 'اختيار صورة الملف اختياري ويستخدم منتقي الصور. النسخة المراجعة لا تطلب الميكروفون أو جهات الاتصال أو موقع GPS. حذف بيانات المتصفح أو التطبيق قد يفقدك الوصول لحساب ضيف غير مربوط؛ ربط الحساب يتيح استعادة الدخول بوسيلة المصادقة.']),
 ('6. مزودو الخدمات ونقل البيانات',[
 'عند تفعيل المصادقة تستخدم الخدمة Google/Firebase Authentication للتحقق من حساب Google أو البريد، وقد يعالج المزود بيانات الحساب والاتصال وفق شروطه وسياسة خصوصيته. تسجيل الدخول عبر Google لا يمنح Plazr كلمة مرور حساب Google.',
 'قد تمر الاتصالات عبر Cloudflare إذا استخدمت جهة التشغيل وكيلها أو نفقها. وتعالج جهة استضافة الخادم وقاعدة البيانات البيانات اللازمة لتشغيل الخدمة. لم تُوثق بعد أسماء جميع مزودي النشر الفعليين أو مواقع التخزين أو النقل الدولي؛ لا ندعي أن البيانات تبقى داخل بلد محدد. يجب استكمال هذه المعلومات قبل اعتماد السياسة للإطلاق.']),
 ('7. الاحتفاظ بالبيانات',[
 'تبقى بيانات الحساب والتقدم والمقتنيات ما دام الحساب موجودًا، إلى أن يُحذف وفق المسار الموضح أدناه. تحفظ المساحة نافذة من أحدث 120 رسالة في مخزن المحادثات الأساسي؛ هذا حد عددي وليس مدة حذف زمنية، ولا يشمل نسخًا خارجية أو محتوى محفوظًا في بلاغ.',
 'تحتفظ محادثة المباراة بنافذة من أحدث 30 رسالة ضمن بيانات الغرفة. الإعداد الافتراضي لصلاحية الغرفة ست ساعات ويُجدد عند النشاط؛ ليس وعدًا بحذف كل آثار المباراة بعد ست ساعات من إنشائها. جلسة المنصة الافتراضية حتى سبعة أيام وقد تُجدد أو تتغير إعداداتها، ويمكن إنهاؤها من الأجهزة.',
 'لم يُعتمد جدول زمني موحد للسجلات التشغيلية الخارجية والنسخ الاحتياطية أو التسجيلات التشخيصية إن فُعلت. حذف الحساب لا ينظف تلك الأنظمة تلقائيًا. هذه فجوة تشغيلية معلنة في المسودة؛ لا نضع مدة حذف غير مطبقة.']),
 ('8. اختياراتك وحذف الحساب',[
 'يمكنك تعديل النبذة والصورة واسم المستخدم وفق قواعد تغييره، وعرض الأجهزة وإبطال جلسة محددة أو جميع الجلسات، وطلب حذف الحساب من الإعدادات أو صفحة حذف الحساب العامة. يتطلب الحذف تأكيدًا وإثباتًا حديثًا لهوية الحساب عند الحاجة.',
 'يوقف طلب الحذف الحساب والجلسات، ثم يحذف هوية Firebase المرتبطة وبيانات الملف والمقتنيات والتقدم وعلاقات الصداقة والرسائل المخزنة في المساحات والسجلات الاجتماعية المرتبطة به ضمن نظام المنصة. حذف هوية Firebase لا يحذف حساب Google الشخصي. إذا تعطل المزود أو التنظيف، يبقى الطلب قيد التنفيذ ويُعاد تلقائيًا؛ لا نعد بموعد إنجاز ثابت لم يُطبق.',
 'قد تبقى نسخ حفظها الآخرون أو سجلات ونسخ احتياطية خارج قاعدة البيانات الاجتماعية كما أوضحنا. يمكنك مراسلة '+email+' بخصوص الاطلاع أو التصحيح أو الحذف أو معالجة بيانات مرتبطة بحسابك. نحتاج إلى التحقق من هوية صاحب الطلب بقدر مناسب؛ لا ترسل كلمة مرور أو رمز دخول.']),
 ('9. الأطفال',[
 'حدد المشغّل أن جمهور المنصة يشمل من هم دون 13 سنة. لكن النسخة الحالية لا تطبق بوابة عمر أو تحققًا من موافقة ولي الأمر، ولا تجربة أطفال منفصلة تحد ظهور الملف والمحادثات. لذلك لا يصح وصفها بأنها مكتملة المتطلبات المخصصة للأطفال اعتمادًا على هذه الصفحة.',
 'يجب استكمال تقييم العمر وموافقة ولي الأمر عند وجوبها، وتقليل البيانات والإعدادات العامة للمستخدمين الصغار ووسائل الإشراف والحقوق الخاصة بأولياء الأمور وفق بلد التشغيل والأسواق المستهدفة قبل اعتماد الإطلاق لهذا الجمهور. لا يُعد ضغط طفل على «موافق» بديلًا عن موافقة ولي أمر قابلة للتحقق. طلبات أولياء الأمور المتعلقة بحساب طفل تُرسل إلى '+email+'.']),
 ('10. الأمان والتغييرات',[
 'تستخدم النسخة الإنتاجية اتصال HTTPS، وجلسات خاصة، وفحص صلاحيات الوصول، وضوابط لمعدل الطلبات. هذه الضوابط لا تعني ضمان أمان مطلقًا. لا تُنشر كلمات المرور أو رموز الدخول في المحادثات أو طلبات الدعم.',
 'تظهر نسخة الوثيقة وتاريخها في هذه الصفحة. عند تغير وظيفة أو مزود أو غرض استخدام أو جمهور مستهدف، يجب تحديث النص وإشعار المستخدمين والحصول على الموافقات المطلوبة قبل التغيير ذي الصلة.'])])
 page('terms','شروط الاستخدام','قواعد الحساب واللعب والمحتوى والمقتنيات الافتراضية.',[
 ('طبيعة الخدمة والأهلية',['Plazr منصة ألعاب اجتماعية تضم مساحات ومحادثات وطاولات للبلياردو والكيرم وأونو وكرة الطاولة. هذه الشروط مسودة مرتبطة بحالة الجاهزية المعلنة؛ لا تعرض قبولًا نهائيًا لشروط لم تُعتمد.','الجمهور المحدد يشمل دون 13 سنة، ولم تُستكمل آلية موافقة ولي الأمر أو شروط مشاركة الأطفال. يجب اعتماد الأهلية وحماية المستخدمين الصغار وفق دولة التشغيل والأسواق المستهدفة؛ لا نعالج ذلك بمجرد إقرار عام من الطفل.']),
 ('الحساب والأمان',['استخدم وسيلة دخول تملكها، ولا تنتحل شخصًا أو جهة أو تشارك بيانات الدخول. اسم المستخدم معرّف عرض وليس إثبات هوية ولا يمنح صلاحية إدارية. لا تعتمد على حساب ضيف غير مربوط كوسيلة مضمونة لاستعادة التقدم بعد فقدان التخزين.','تغيير اسم المستخدم والمقتنيات والرصيد يخضع للقواعد المعروضة داخل الخدمة. حماية الحساب تشمل إدارة الأجهزة وإلغاء الجلسات، ويمكنك حذف الحساب بالطريقة الموضحة في سياسة الخصوصية.']),
 ('المحتوى والسلوك',['تحتفظ بحقوق المحتوى الذي تنشره، وتتحمل مسؤولية امتلاك حق نشره. تمنح المنصة إذنًا غير حصري بالقدر اللازم لتخزينه ونقله وعرضه للمستلمين المسموحين وإدارته وتشغيل ميزات الخدمة، لا ترخيصًا غير محدود لبيعه أو استخدامه خارج هذه الأغراض.','يُمنع التحرش والتهديد والتشهير والانتحال ونشر بيانات الغير أو المحتوى الجنسي أو الاستغلالي، وخصوصًا ما يتعلق بالأطفال، والاحتيال والرسائل المزعجة والغش وتعطيل الخدمة وتجاوز الصلاحيات أو استغلال الثغرات. راجع قواعد المجتمع للإبلاغ والإشراف.']),
 ('المباريات والعملات الافتراضية',['المباريات للتفاعل واللعب؛ نتيجة الاتصال أو الانسحاب أو نفاد الوقت تُعالج وفق قواعد اللعبة والخادم. قد يتأثر اللعب بانقطاع الشبكة أو الأعطال، ولا يعني الفوز استحقاق مبلغ مالي.','الرصيد والمقتنيات الحالية افتراضية للاستخدام داخل المنصة، وليست وديعة مالية أو وسيلة دفع أو أصلًا قابلًا للسحب النقدي. لا يتضمن الإصدار الحالي مسار شراء بأموال حقيقية؛ لا تُرسل مبالغ لأفراد يدعون بيع رصيد خارج وسيلة رسمية معلنة. أي دفع مستقبلي يحتاج شروطًا معلنة وآليات متجر وفوترة واستعادة مناسبة قبل تفعيله.']),
 ('الإشراف والتواصل',['قد يُكتم مستخدم أو يُخرج من مساحة أو يُحظر أو يُزال محتوى مخالف بحسب الصلاحيات والواقعة. يمكن الإبلاغ من ملف اللاعب، ومراسلة '+email+' بشأن قرار أو بلاغ، مع توفير بيانات كافية دون كلمات مرور أو رموز جلسات.','لا نقدم وعدًا بزمن استجابة ثابت أو مراقبة بشرية على مدار الساعة لم يُجهز تشغيلها. ينبغي تجهيز إجراءات حماية الأطفال وتصعيد البلاغات قبل اعتماد الخدمة لجمهورها المحدد.']),
 ('الملكية والتوافر والحقوق',['حقوق العلامة والبرمجيات والمحتوى الخاص بالمنصة تعود لأصحابها، وتبقى حقوق الأصول المرخصة لمالكيها وفق تراخيصها. لا تمنح هذه الشروط ملكية حقوق طرف ثالث للمنصة، ولا تصريحًا بانتهاكها.','قد تتوقف الخدمة للصيانة أو تتغير الميزات، ويجب الإعلان عن تغييرات تؤثر جوهريًا في المستخدمين ومقتنياتهم وفق ما يلزم. لا تسقط هذه الشروط حقوقًا إلزامية للمستخدم، ولا تتضمن إعفاءً يتجاوز ما يسمح به القانون المنطبق.','بيانات المشغّل ودولة التشغيل والاختصاص وتسوية الشكاوى لم تستكمل في هذه المسودة. لا تُفرض جهة قضائية أو قانون دولة افتراضي.'])])
 page('about','من نحن','Plazr: ألعاب وجمعة في مكان واحد.',[
 ('فكرة Plazr',['Plazr مشروع منصة ألعاب اجتماعية تجمع اللاعبين في مساحات للمحادثة وطاولات للعب. الألعاب المتاحة في النسخة الحالية: البلياردو، الكيرم، أونو وكرة الطاولة.','يمكنك الدخول كضيف وربط حساب لحفظ الوصول إلى تقدمك، وتخصيص ملفك بنبذة وصورة ومقتنيات، وإدارة أجهزتك من الإعدادات. تتاح الواجهة على الويب وفي تطبيق الهاتف بحسب النسخة المنشورة.']),
 ('المسؤولية والوضوح',['اسم المشروع هو Plazr. '+('الجهة المشغلة: '+c['operatorLegalName']+'.' if c.get('operatorLegalName') else 'لم يُثبت في هذه الوثائق اسم شركة مسجلة أو هوية قانونية للمالك؛ يجب استكمالها قبل الاعتماد النهائي.'),'لا نعرض وعودًا بأن المنتج معتمد من متجر أو مستوفٍ لمتطلبات الأطفال لمجرد نشر صفحات قانونية. حالة هذه النسخة موضحة أعلى الوثائق.']),
 ('التواصل',['قناة الدعم وطلبات الخصوصية المحددة: '+email+'. العنوان لا يعني تلقائيًا أن صندوق البريد أصبح مفعّلًا؛ تأكيد تشغيله من مسؤول النشر مطلوب قبل الإطلاق.'])])
 page('contact','التواصل والدعم','المساعدة وطلبات الخصوصية والبلاغات.',[
 ('راسل Plazr',['عنوان الدعم وطلبات الخصوصية: '+email+'. هذه القناة تستقبل يدويًا بعد تفعيل الصندوق؛ ليست نظام تذاكر داخل المنصة، ولم يُعتمد وقت استجابة مضمون.']),
 ('ماذا تتضمن رسالتك؟',['اذكر نوع الطلب: مشكلة حساب، خلل لعبة، بلاغ محتوى، اعتراض على إجراء إشراف، طلب خصوصية أو طلب متعلق بطفل. أضف اسم المستخدم ومعرّف الطاولة إن وجد وتوقيت المشكلة ووصفًا مختصرًا، وصورة للشاشة إذا احتجت مع إخفاء بيانات غيرك غير اللازمة.','لا ترسل كلمات المرور أو رموز التحقق أو توكنات الجلسة أو مستندات هوية عبر الشات العام. لا نطلب كلمة مرور Google؛ إذا احتجنا للتحقق من طلب حساب فسنحدد وسيلة مناسبة ومحدودة.']),
 ('الإبلاغ من داخل المنصة',['افتح ملف اللاعب واختر الإبلاغ، واشرح الواقعة. إجراءات كتم العضو أو إخراجه أو حظره من المساحة تعتمد صلاحيات الإشراف. لا نصف حظرًا شخصيًا أو تصفية آلية بأنها موجودة إذا لم تنفذها النسخة الحالية.','يمكن لولي الأمر التواصل بشأن حساب طفل مع توضيح علاقته بالطلب، دون نشر بيانات الطفل في مساحة عامة. توثيق الموافقات وإدارة تجربة الأطفال يحتاجان الاستكمال المعلن في صفحة الأطفال.']),
 ('حذف الحساب',['يمكن بدء حذف الحساب من إعدادات الحساب أو صفحة حذف الحساب العامة. تُعرض نتيجة الطلب وما إذا كان الحذف مكتملًا أو قيد التنفيذ؛ مراجعة سياسة الخصوصية توضح ما يدخل في الحذف وحدوده.'])])
 page('community-guidelines','قواعد المجتمع','احترام اللاعبين وحماية المحادثات واللعب.',[
 ('تعامل باحترام',['لا تستخدم الإهانات أو التهديد أو خطاب الكراهية أو التنمر أو الاستهداف المتكرر. لا تنتحل هوية لاعب أو مشرف ولا تطلب كلمات المرور أو رموز الدخول.']),
 ('احمِ الخصوصية والمستخدمين الصغار',['لا تنشر اسمًا حقيقيًا أو رقم هاتف أو عنوانًا أو صورة خاصة لغيرك دون حق. يُمنع المحتوى الجنسي والاستغلال والتحرش وطلب صور خاصة أو محاولة استدراج الأطفال أو نقلهم لاتصالات غير آمنة.','تتطلب المنصة التي تشمل الأطفال إجراءات إضافية تتجاوز هذه القواعد النصية. النسخة الحالية لم تستكمل مسار موافقة ولي الأمر أو تجربة أطفال منفصلة؛ راجع صفحة الأطفال قبل اعتماد الإطلاق.']),
 ('العب بنزاهة',['يُمنع الغش واستغلال الثغرات والتلاعب بالحركات أو المكافآت أو انتحال الأدوار الإدارية، وإغراق المحادثات أو تعمد تعطيل الطاولات والخدمات. أسماء الدول للمساحات لا تمنح أي عضو سلطة على غيره.']),
 ('بلّغ بدل التصعيد',['استخدم الإبلاغ في ملف اللاعب، أو '+email+' بعد تفعيله. يتخذ المشرفون إجراءات ضمن صلاحياتهم مثل الكتم والإخراج والحظر. يمكن مراسلة الدعم بشأن قرار، دون ضمان رد فوري أو مراقبة دائمة غير مجهزة.'])])
 page('children','الأطفال والعائلة — حالة الجاهزية','إفصاح صريح عن الفجوة بين الجمهور المحدد وما تنفذه النسخة الحالية.',[
 ('الجمهور المحدد',['أبلغ المشغّل أن المنصة تشمل من هم دون 13 سنة. لا يوجد في النسخة المراجعة مسار لتحديد العمر أو موافقة ولي أمر قابلة للتحقق أو لوحة لحقوق ولي الأمر. النص وحده لا يحل هذا النقص.']),
 ('ما الذي يحدث حاليًا؟',['قد تُجمع معرّفات حساب وجلسة وبيانات اتصال ومحتوى ورسائل وتقدم حتى للضيف. الملفات والمحادثات الاجتماعية يمكن أن تكون ظاهرة للآخرين. البريد مخفي عن الملف العام، لكن ذلك ليس تجربة خصوصية مخصصة للأطفال.']),
 ('ما الذي يلزم قبل الاعتماد؟',['تحديد دولة التشغيل والأسواق والأعمار بدقة، وتقييم متطلبات جمع بيانات الأطفال والموافقات والتحقق من ولي الأمر وتقليل البيانات والخصوصية الافتراضية والمحادثات والإشراف والبلاغات وطلبات الحذف والإفصاحات في المتاجر. لا يفترض هذا التقييم أن سن 13 وحده هو الحد القانوني في كل بلد.','إما تنفيذ تجربة أطفال مناسبة فعليًا، أو تغيير الجمهور المخطط واعتماد القيود المناسبة فعليًا. لم يغيّر نشر هذه الصفحة جمهور المنصة تلقائيًا، ولم يضف هذه الضوابط في الخلفية.']),
 ('تواصل ولي الأمر',['طلبات الاستفسار أو حذف بيانات مرتبطة بطفل توجه إلى '+email+' بعد تفعيل البريد. لا ترسل بيانات الطفل أو رموز دخوله في المحادثات العامة. سياسة الخصوصية تشرح مسار حذف الحساب وحدود حذف النسخ الخارجية.'])])
 data={'brand':c['brand'],'revision':c['revision'],'draft':draft,'supportEmail':email,'operatorLegalName':c.get('operatorLegalName'),'operatingCountry':c.get('operatingCountry'),'reviewItems':missing,'pages':pages}
